// potential[b] - potential[a] = difference という制約を管理するUnion-Find。
template <class Weight>
struct WeightedDsu {
  std::vector<int> parent_or_size;
  std::vector<Weight> difference_to_parent;
  int components;

  explicit WeightedDsu(int n)
      : components(n) {
    assert(n >= 0);
    parent_or_size.assign(n, -1);
    difference_to_parent.assign(n, Weight{});
  }

  int leader(int vertex) {
    check_vertex(vertex);
    if (parent_or_size[vertex] < 0) return vertex;
    const int parent = parent_or_size[vertex];
    const int root = leader(parent);
    difference_to_parent[vertex] += difference_to_parent[parent];
    parent_or_size[vertex] = root;
    return root;
  }

  Weight potential(int vertex) {
    leader(vertex);
    return difference_to_parent[vertex];
  }

  bool same(int a, int b) { return leader(a) == leader(b); }

  // potential[b] - potential[a]。same(a,b)==trueの時だけ呼ぶ。
  Weight difference(int a, int b) {
    assert(same(a, b));
    return potential(b) - potential(a);
  }

  // 制約が追加可能ならtrue。既に連結済みでも整合すればtrue。
  // 現在の制約と矛盾する場合はfalseで、状態を変更しない。
  bool unite(int a, int b, Weight difference_b_minus_a) {
    check_vertex(a);
    check_vertex(b);
    difference_b_minus_a += potential(a);
    difference_b_minus_a -= potential(b);
    int root_a = leader(a);
    int root_b = leader(b);
    if (root_a == root_b) return difference_b_minus_a == Weight{};
    if (-parent_or_size[root_a] < -parent_or_size[root_b]) {
      std::swap(root_a, root_b);
      difference_b_minus_a = -difference_b_minus_a;
    }
    parent_or_size[root_a] += parent_or_size[root_b];
    parent_or_size[root_b] = root_a;
    difference_to_parent[root_b] = difference_b_minus_a;
    --components;
    return true;
  }

  int size(int vertex) { return -parent_or_size[leader(vertex)]; }
  int component_count() const { return components; }

 private:
  void check_vertex(int vertex) const {
    assert(0 <= vertex && vertex < static_cast<int>(parent_or_size.size()));
  }
};
#endif  // AHC_BUNDLE_A6F39B81617F56FA0A0047271CFCCEBC1F3755C620B7ADCD18B1E2C3B3367DED
// end: library/weighted-dsu.hpp

// Greedily accumulate relative start constraints on equal-length circles.
// '.' is an unknown symbol. A conflicting join changes no component or pattern.
class CircularPatternComponents {
    int n_;
    WeightedDsu<int> dsu_;
    std::vector<std::string> model_;
    int normalize(int x) const {int r=x%n_;return r<0?r+n_:r;}
public:
    CircularPatternComponents(int period,const std::vector<std::string>& patterns)
        :n_(period),dsu_(static_cast<int>(patterns.size())),model_(patterns) {
        if(period<=0) throw std::invalid_argument("period must be positive");
        for(auto& p:model_) {
            if(p.size()>static_cast<std::size_t>(period)) throw std::invalid_argument("pattern exceeds period");
            p.resize(period,'.');
        }
    }
    bool join(int a,int b,int b_start_minus_a) {
        const int x=dsu_.leader(a),y=dsu_.leader(b);
        const int d=normalize(b_start_minus_a);
        if(x==y) return normalize(dsu_.difference(a,b))==d;
        const int shift=normalize(dsu_.potential(a)+d-dsu_.potential(b));
        for(int i=0;i<n_;++i) {
            char c=model_[y][i],p=model_[x][(i+shift)%n_];
            if(c!='.'&&p!='.'&&p!=c)return false;
        }
        dsu_.unite(a,b,d);
        if(dsu_.leader(a)==x) {
            for(int i=0;i<n_;++i)if(model_[y][i]!='.')model_[x][(i+shift)%n_]=model_[y][i];
        } else {
            for(int i=0;i<n_;++i)if(model_[x][i]!='.')model_[y][(i-shift+n_)%n_]=model_[x][i];
        }
        return true;
    }
    int leader(int i) {return dsu_.leader(i);}
    int offset(int i) {return normalize(dsu_.potential(i));}
    const std::string& pattern(int i) {return model_[dsu_.leader(i)];}
};
#endif  // AHC_BUNDLE_76C766EBC66DC56D75EACB14FE6DFD0F089946903CCA0918251B56E48544257C
